}, {
  "tStartMs": 1279728,
  "dDurationMs": 1235,
  "segs": [ {
    "utf8": "東京首爾都有做"
  } ]
}, {
  "tStartMs": 1280963,
  "dDurationMs": 1985,
  "segs": [ {
    "utf8": "既然這邊現在應該被保存"
  } ]
}, {
  "tStartMs": 1282948,
  "dDurationMs": 2703,
  "segs": [ {
    "utf8": "直接就是把這邊買或長租下來"
  } ]
}, {
  "tStartMs": 1285651,
  "dDurationMs": 3303,
  "segs": [ {
    "utf8": "然後等於你再用正常的租金租出去"
  } ]
}, {
  "tStartMs": 1288954,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "讓一些本來我們要保有"
  } ]
}, {
  "tStartMs": 1290756,
  "dDurationMs": 2202,
  "segs": [ {
    "utf8": "在這邊的店或文化在那邊存活"
  } ]
}, {
  "tStartMs": 1292958,
  "dDurationMs": 1218,
  "segs": [ {
    "utf8": "所以換句話說"
  } ]
}, {
  "tStartMs": 1294176,
  "dDurationMs": 2385,
  "segs": [ {
    "utf8": " 都市它不必停止前進"
  } ]
}, {
  "tStartMs": 1296561,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "但是我們可以有些想法"
  } ]
}, {
  "tStartMs": 1298163,
  "dDurationMs": 1285,
  "segs": [ {
    "utf8": "去保留一些記憶"
  } ]
}, {
  "tStartMs": 1299448,
  "dDurationMs": 1167,
  "segs": [ {
    "utf8": "對"
  } ]
}, {
  "tStartMs": 1300615,
  "dDurationMs": 1318,
  "segs": [ {
    "utf8": "真的 對於"
  } ]
}, {
  "tStartMs": 1301933,
  "dDurationMs": 2086,
  "segs": [ {
    "utf8": "我覺得對我們這個世代的人來講"
  } ]
}, {
  "tStartMs": 1304019,
  "dDurationMs": 901,
  "segs": [ {
    "utf8": "就像剛剛提到"
  } ]
}, {
  "tStartMs": 1304920,
  "dDurationMs": 2302,
  "segs": [ {
    "utf8": "如果再看到光華商場的看板"
  } ]
}, {
  "tStartMs": 1307222,
  "dDurationMs": 1668,
  "segs": [ {
    "utf8": "那真的會"
  } ]
}, {
  "tStartMs": 1308890,
  "dDurationMs": 1452,
  "segs": [ {
    "utf8": "真的會流眼淚"
  } ]
}, {
  "tStartMs": 1310342,
  "dDurationMs": 1018,
  "segs": [ {
    "utf8": "我覺得中華商場是"
  } ]
}, {
  "tStartMs": 1311360,
  "dDurationMs": 1234,
  "segs": [ {
    "utf8": "因為中華商場那時候 "
  } ]
}, {
  "tStartMs": 1312594,
  "dDurationMs": 1668,
  "segs": [ {
    "utf8": "拆掉我還很小"
  } ]
}, {
  "tStartMs": 1314262,
  "dDurationMs": 851,
  "segs": [ {
    "utf8": "所以那邊的記憶 "
  } ]
}, {
  "tStartMs": 1315113,
  "dDurationMs": 1552,
  "segs": [ {
    "utf8": "我大概就不復存在"
  } ]
}, {
  "tStartMs": 1316665,
  "dDurationMs": 1735,
  "segs": [ {
    "utf8": "但是你看像記憶也包含 "
  } ]
}, {
  "tStartMs": 1318400,
  "dDurationMs": 751,
  "segs": [ {
    "utf8": "不是只有空間"
  } ]
}, {
  "tStartMs": 1319151,
  "dDurationMs": 1801,
  "segs": [ {
    "utf8": "還包含小說"
  } ]
}, {
  "tStartMs": 1320952,
  "dDurationMs": 1035,
  "segs": [ {
    "utf8": "像我上次 "
  } ]
}, {
  "tStartMs": 1321987,
  "dDurationMs": 2369,
  "segs": [ {
    "utf8": "我之前看到有一部劇叫"
  } ]
}, {
  "tStartMs": 1324356,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "《天橋上的魔術師》"
  } ]
}, {
  "tStartMs": 1325657,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "《天橋上的魔術師》"
  } ]
}, {
  "tStartMs": 1327559,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "它就在寫那邊的記憶"
  } ]
}, {
  "tStartMs": 1328660,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "它在講中華商場"
  } ]
}, {
  "tStartMs": 1329861,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "對 我後來才發現它原本是"
  } ]
}, {
  "tStartMs": 1331663,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "它應該原本是著作"
  } ]
}, {
  "tStartMs": 1333465,
  "dDurationMs": 1485,
  "segs": [ {
    "utf8": "然後後來才把它改變成戲劇"
  } ]
}, {
  "tStartMs": 1334950,
  "dDurationMs": 500,
  "segs": [ {
    "utf8": "沒錯"
  } ]
}, {
  "tStartMs": 1335450,
  "dDurationMs": 701,
  "segs": [ {
    "utf8": "但我就覺得說"
  } ]
}, {
  "tStartMs": 1336151,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "那因為它就是在那一代的人"
  } ]
}, {
  "tStartMs": 1338053,
  "dDurationMs": 2886,
  "segs": [ {
    "utf8": "而且就是有各縣市來的人"
  } ]
}, {
  "tStartMs": 1340939,
  "dDurationMs": 1969,
  "segs": [ {
    "utf8": "還有就是那時候49年"
  } ]
}, {
  "tStartMs": 1342908,
  "dDurationMs": 1701,
  "segs": [ {
    "utf8": "大家一起來到台灣的人"
  } ]
}, {
  "tStartMs": 1344609,
  "dDurationMs": 2303,
  "segs": [ {
    "utf8": "然後也有本來就住在這邊的人"
  } ]
}, {
  "tStartMs": 1346912,
  "dDurationMs": 1601,
  "segs": [ {
    "utf8": "但是因為大家都要去那邊買東西"
  } ]
}, {
  "tStartMs": 1348513,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "因為那時候買東西非常多元"
  } ]
}, {
  "tStartMs": 1350115,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "所以大家都要去那邊買東西"
  } ]
}, {
  "tStartMs": 1351416,
  "dDurationMs": 2586,
  "segs": [ {
    "utf8": "所以那邊就是當時大家的記憶"
  } ]
}, {
  "tStartMs": 1354002,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "然後那時候不是皮鞋嗎"
  } ]
}, {
  "tStartMs": 1355303,
  "dDurationMs": 401,
  "segs": [ {
    "utf8": "什麼的"
  } ]
}, {
  "tStartMs": 1355704,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "對 那時候是皮鞋 制服"
  } ]
}, {
  "tStartMs": 1357806,
  "dDurationMs": 984,
  "segs": [ {
    "utf8": "你看像我 "
  } ]
}, {
  "tStartMs": 1358790,
  "dDurationMs": 2419,
  "segs": [ {
    "utf8": "我自己我剛剛講說我是宜蘭人"
  } ]
}, {
  "tStartMs": 1361209,
  "dDurationMs": 1318,
  "segs": [ {
    "utf8": "然後媽媽是台南人 "
  } ]
}, {
  "tStartMs": 1362527,
  "dDurationMs": 2286,
  "segs": [ {
    "utf8": "就是所謂的純本省人"
  } ]
}, {
  "tStartMs": 1364813,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "可是以前小時候 "
  } ]
}, {
  "tStartMs": 1366114,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "還是會去那邊吃真北平"
  } ]
}, {
  "tStartMs": 1368216,
  "dDurationMs": 2586,
  "segs": [ {
    "utf8": "那個真北平是我們的記憶"
  } ]
}, {
  "tStartMs": 1370802,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "然後那時候也有很多日本的電器"
  } ]
}, {
